starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "app_name" {
  description = "Application name."
  type        = string
  default     = "terraform-arena"
}

variable "aws_region" {
  description = "AWS region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_s3_bucket" "this" {
  # TODO - Complete the bucket resource.
  # Set the bucket argument from the input variable.
}
